selector:
/* Original Arbana AH / glass / glass-cap: the white cap moves independently
   of the buttons, including transitions between host and embedded sections. */
:is(#keysUnifiedPrototype#keysUnifiedPrototype,.keys-module-screen) .keys-bottom-nav::before

